def solve():
    def is_valid(U):
        # Rule 1: x in U and x is even => x/2 in U
        for x in U:
            if x % 2 == 0:
                if x // 2 not in U:
                    return False

        # Rule 2: x+y in U => x in U or y in U
        # This is equivalent to: x not in U and y not in U => x+y not in U
        # So we check the complement R = {1, ..., 191} - U
        R = [i for i in range(1, 192) if i not in U]
        for x in R:
            for y in R:
                if x + y <= 191:
                    if (x + y) not in R:
                        return False
        return True

    # We want to maximize sum(U) such that |U| <= 96
    # Let's try some candidates for U.
    # Candidate 1: all odd numbers
    U1 = [i for i in range(1, 192) if i % 2 != 0]
    print(f"U1 sum: {sum(U1)}, valid: {is_valid(U1)}")

    # Candidate 2: some large numbers.
    # If 191 is in U, then for all x, either x or 191-x must be in U.
    # Let's try to build U by picking one from each pair {x, 191-x}.
    # Also need to satisfy x in U => odd(x) in U.

    # Let's try to pick U as the 96 largest numbers that satisfy x in U => odd(x) in U.
    # This means if we pick an even number, we must also pick its odd divisor.

    # Let's use a greedy approach to find a large sum.
    # We want to pick numbers from 191 downwards.
    U = set()
    for x in range(191, 0, -1):
        if len(U) < 96:
            # Check if adding x and all its necessary odd divisors keeps |U| <= 96
            needed = set()
            curr = x
            while curr > 0:
                if curr % 2 == 0:
                    needed.add(curr)
                    curr //= 2
                else:
                    needed.add(curr)
                    break

            new_U = U | needed
            if len(new_U) <= 96:
                U = new_U

    # Now check if this U satisfies the semigroup condition.
    # If not, we can try to adjust it.
    print(f"Greedy U sum: {sum(U)}, valid: {is_valid(U)}")

